package com.ianblk.zianmobs;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.effect.*;
import net.minecraft.world.item.*;
import net.minecraft.world.InteractionHand;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.event.entity.player.CriticalHitEvent;
final class AbilitySmoke {
 private static void check(boolean ok,String message){if(!ok)throw new IllegalStateException(message);}
 static void run(ServerPlayer p){var main=p.getMainHandItem();float health=p.getHealth();var persistent=p.getPersistentData().copy();var cow=EntityType.COW.create(p.serverLevel());cow.getAttribute(Attributes.MAX_HEALTH).setBaseValue(200);cow.setHealth(200);cow.moveTo(p.getX(),p.getY(),p.getZ()+3,0,0);cow.setNoAi(true);p.serverLevel().addFreshEntity(cow);
 try{
  for(var spec:Gear.CATALOG){p.setItemSlot(EquipmentSlot.MAINHAND,Gear.ITEMS.get(spec.id()).get().getDefaultInstance());cow.invulnerableTime=0;for(var effect:java.util.List.of(MobEffects.POISON,MobEffects.WITHER,MobEffects.WEAKNESS,GearAbilities.BLEEDING))cow.removeEffect(effect);cow.hurt(p.damageSources().playerAttack(p),1);var expected=switch(spec.pack()){case "Carnivoret"->spec.id().endsWith("_scythe")?null:MobEffects.POISON;case "Ruby"->GearAbilities.BLEEDING;case "Dark Queen"->MobEffects.WITHER;case "Purple World"->MobEffects.WEAKNESS;default->null;};if(expected!=null)check(cow.hasEffect(expected)&&cow.getEffect(expected).getDuration()==40,"Collection proc missing: "+spec.id());if(spec.id().endsWith("_scythe"))check(!cow.hasEffect(MobEffects.POISON)&&Tuning.defaults(p.getMainHandItem().getItem()).damage()==14,"Scythe damage/exclusion");check(p.getMainHandItem().get(net.minecraft.core.component.DataComponents.LORE).lines().stream().noneMatch(c->c.getString().toLowerCase(java.util.Locale.ROOT).contains("netherita")),"Technical lore remains");}
  for(String id:java.util.List.of("carnivoret_weapon_set_scythe","valentines_animated_weapon_and_tool_set_v1_sword","toffy_master_sword")){p.getPersistentData().getCompound(net.minecraft.world.entity.player.Player.PERSISTED_NBT_TAG).remove("ZianMobsCooldown_healing");p.setHealth(5);p.removeEffect(MobEffects.REGENERATION);p.setItemSlot(EquipmentSlot.MAINHAND,Gear.ITEMS.get(id).get().getDefaultInstance());cow.invulnerableTime=0;NeoForge.EVENT_BUS.post(new CriticalHitEvent(p,cow,1.5f,true));cow.hurt(p.damageSources().playerAttack(p),1);boolean master=id.equals("toffy_master_sword");check(Math.abs(p.getHealth()-(5+p.getMaxHealth()*(master?.2f:.1f)))<.01,"Critical healing "+id);check(p.getEffect(MobEffects.REGENERATION).getDuration()==(master?200:100),"Regen duration");float after=p.getHealth();cow.invulnerableTime=0;NeoForge.EVENT_BUS.post(new CriticalHitEvent(p,cow,1.5f,true));cow.hurt(p.damageSources().playerAttack(p),1);check(p.getHealth()==after,"Healing cooldown bypass");}
  p.getPersistentData().getCompound(net.minecraft.world.entity.player.Player.PERSISTED_NBT_TAG).remove("ZianMobsCooldown_healing");p.setHealth(5);cow.invulnerableTime=0;cow.setInvulnerable(true);NeoForge.EVENT_BUS.post(new CriticalHitEvent(p,cow,1.5f,true));cow.hurt(p.damageSources().playerAttack(p),1);check(p.getHealth()==5,"Invulnerable target triggered healing");cow.setInvulnerable(false);
  var deadline=p.getPersistentData().getCompound(net.minecraft.world.entity.player.Player.PERSISTED_NBT_TAG);deadline.putLong("ZianMobsCooldown_shield",System.currentTimeMillis()+45000);deadline.remove("ZianMobsShield30");check(GearAbilities.acquire(p,"shield",30),"Old shield wait was not migrated to 30 seconds");deadline.remove("ZianMobsCooldown_shield");
  var bow=Gear.ITEMS.get("ruby_vol_1_bow").get().getDefaultInstance();var arrow=new net.minecraft.world.entity.projectile.Arrow(p.level(),p,new ItemStack(Items.ARROW),bow);cow.removeEffect(GearAbilities.BLEEDING);p.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.STICK));cow.invulnerableTime=0;cow.hurt(p.damageSources().arrow(arrow,p),1);check(cow.hasEffect(GearAbilities.BLEEDING),"Arrow lost original collection after weapon switch");arrow.discard();
  p.setItemSlot(EquipmentSlot.MAINHAND,Gear.ITEMS.get("toffy_hylian_shield").get().getDefaultInstance());p.startUsingItem(InteractionHand.MAIN_HAND);p.removeEffect(MobEffects.REGENERATION);p.removeEffect(MobEffects.DAMAGE_RESISTANCE);var container=new net.neoforged.neoforge.common.damagesource.DamageContainer(p.damageSources().mobAttack(cow),4);var block=new net.neoforged.neoforge.event.entity.living.LivingShieldBlockEvent(p,container,false);NeoForge.EVENT_BUS.post(block);check(!p.hasEffect(MobEffects.DAMAGE_RESISTANCE),"Non-block triggered shield buff");block=new net.neoforged.neoforge.event.entity.living.LivingShieldBlockEvent(p,container,true);block.setCanceled(true);NeoForge.EVENT_BUS.post(block);check(!p.hasEffect(MobEffects.DAMAGE_RESISTANCE),"Canceled block triggered buff");block=new net.neoforged.neoforge.event.entity.living.LivingShieldBlockEvent(p,container,true);NeoForge.EVENT_BUS.post(block);check(p.getEffect(MobEffects.DAMAGE_RESISTANCE).getDuration()==200&&p.getEffect(MobEffects.REGENERATION).getDuration()==200,"Shield buffs missing");p.removeEffect(MobEffects.DAMAGE_RESISTANCE);NeoForge.EVENT_BUS.post(new net.neoforged.neoforge.event.entity.living.LivingShieldBlockEvent(p,container,true));check(!p.hasEffect(MobEffects.DAMAGE_RESISTANCE),"Shield cooldown bypass");p.stopUsingItem();
  check(GearAbilities.acquire(p,"test",30)&&!GearAbilities.acquire(p,"test",30),"Persistent cooldown failed");var tag=p.getPersistentData().copy();p.getPersistentData().merge(tag);check(!GearAbilities.acquire(p,"test",30),"Restored deadline lost");
  for(String id:java.util.List.of("ruby_vol_1_staff","dark_queen_staff","valentines_animated_weapon_and_tool_set_v1_staff","carnivoret_weapon_set_staff")){p.getPersistentData().getCompound(net.minecraft.world.entity.player.Player.PERSISTED_NBT_TAG).remove("ZianMobsCooldown_staff");var item=Gear.ITEMS.get(id).get();p.setItemSlot(EquipmentSlot.MAINHAND,item.getDefaultInstance());check(item.use(p.level(),p,InteractionHand.MAIN_HAND).getResult().consumesAction(),"Staff did not cast");check(!item.use(p.level(),p,InteractionHand.MAIN_HAND).getResult().consumesAction(),"Staff cooldown bypass");}
  var projectile=new NpcProjectile(Mobs.PROJECTILE.get(),p,p.level(),"WITHER",4);projectile.setWeapon(Gear.ITEMS.get("ruby_vol_1_staff").get().getDefaultInstance());var data=projectile.saveWithoutId(new net.minecraft.nbt.CompoundTag());var restored=Mobs.PROJECTILE.get().create(p.level());restored.readAdditionalSaveData(data);check(GearAbilities.id(restored.weapon()).equals("ruby_vol_1_staff"),"Projectile weapon lost on save");cow.invulnerableTime=0;restored.setOwner(p);restored.smokeImpact(cow.position(),cow);check(cow.hasEffect(GearAbilities.BLEEDING),"Staff collection proc missing");
 }finally{p.stopUsingItem();p.removeEffect(MobEffects.DAMAGE_RESISTANCE);p.setItemSlot(EquipmentSlot.MAINHAND,main);p.setHealth(health);p.removeEffect(MobEffects.REGENERATION);p.getPersistentData().remove(net.minecraft.world.entity.player.Player.PERSISTED_NBT_TAG);p.getPersistentData().merge(persistent);for(var entity:p.serverLevel().getEntitiesOfClass(NpcProjectile.class,p.getBoundingBox().inflate(32)))if(entity.getOwner()==p)entity.discard();cow.discard();}
 }
}
